import itertools, json, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
N = 15
# Precompute possible triples
triples = []
for a, b in itertools.combinations(L, 2):
    s = a + b
    if s in L and s not in (a, b):
        triples.append((a, b, s))
# Backtracking search for exact cover
L_list = list(L)
used = set()
solution = []

def search(start):
    if len(solution) == N:
        if used == L:
            return True
        return False
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        solution.append((a, b, c))
        used.update([a, b, c])
        if search(i + 1):
            return True
        solution.pop()
        used.difference_update([a, b, c])
    return False
found = search(0)
if found:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "method": "backtracking"}
print('WITNESS:', json.dumps(witness))

